class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;

        for (int i = 1; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) {
                return false;
            }
        }

        boolean[][] dp = new boolean[n][n + 1];
        dp[0][0] = true;

        for (int i = 1; i < n; i++) {
            for (int j = i - 1; j >= 0; j--) {
                int jump = stones[i] - stones[j];

                // At stone j, the next jump cannot exceed j + 1.
                if (jump > j + 1) {
                    break;
                }

                dp[i][jump] = dp[j][jump - 1]
                        || dp[j][jump]
                        || dp[j][jump + 1];

                if (i == n - 1 && dp[i][jump]) {
                    return true;
                }
            }
        }

        return false;
    }
}

